<template><section class="module-page module-composed-page"><header class="module-heading"><div><h1>资源管理</h1><p>统一查看课程资源、发布状态和下发任务。</p></div><el-button type="primary" icon="el-icon-reading" @click="$router.push('/management/courses')">进入课程管理</el-button></header><div class="module-table-wrap"><el-table v-loading="loading" :data="rows" empty-text="暂无资源"><el-table-column prop="name" label="资源名称" min-width="220" /><el-table-column prop="resourceType" label="类型" width="120" /><el-table-column prop="courseName" label="所属课程" min-width="180" /><el-table-column label="状态" width="100"><template slot-scope="s"><el-tag size="small" :type="s.row.enabled?'success':'info'">{{ s.row.enabled?'启用':'停用' }}</el-tag></template></el-table-column><el-table-column label="操作" width="280" align="right"><template slot-scope="s"><el-button size="small" :loading="busyId===s.row.resourceId" @click="toggle(s.row)">{{ s.row.enabled?'停用资源':'启用资源' }}</el-button><el-button size="small" :loading="busyId===s.row.resourceId" :disabled="!s.row.enabled" @click="deliverAll(s.row)">下发到全部环境</el-button></template></el-table-column></el-table></div></section></template>
<script>
import { listAdminCourses, setCourseResourceEnabled, deliverCourseResourceToAll } from '@/api/Courses'
export default { data:()=>({loading:false,busyId:'',rows:[]}), created(){this.load()}, methods:{async load(){this.loading=true;try{const r=await listAdminCourses();this.rows=(r.data||[]).reduce((all,item)=>all.concat((item.resources||[]).map(resource=>Object.assign({},resource,{courseName:item.course.name}))),[])}finally{this.loading=false}},async toggle(row){this.busyId=row.resourceId;try{await setCourseResourceEnabled(row.resourceId,!row.enabled);await this.load()}finally{this.busyId=''}},async deliverAll(row){try{await this.$confirm(`将把“${row.name}”发送到该课程全部用户的实训环境，是否继续？`,'确认下发',{type:'warning'})}catch(e){return}this.busyId=row.resourceId;try{await deliverCourseResourceToAll(row.resourceId);this.$message.success('下发任务已提交')}finally{this.busyId=''}}} }
</script>
